import React, { useState, useEffect, useRef } from 'react';
import { useLocation } from 'react-router-dom';
import styles from '../css/chat.module.css';

const Chat = () => {
  const location = useLocation();
  const { personality, name: chatbotName = '챗봇' } = location.state || {};  // '/settings'에서 전달된 값
  const [userInput, setUserInput] = useState('');
  const [chatHistory, setChatHistory] = useState([]);
  const [currentDateTime, setCurrentDateTime] = useState('');
  const [error, setError] = useState(null);
  const chatEndRef = useRef(null);  // 맨 밑의 메시지 참조용

  // 현재 날짜와 시간을 반환하는 함수 (날짜 + 시:분 형식)
  const getCurrentDateTime = () => {
    const now = new Date();
    const date = now.toLocaleDateString('ko-KR', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      weekday: 'long',  // 요일을 포함하도록 설정
    }); // 예: "2025년 1월 11일 금요일"
    const time = now.toLocaleTimeString('ko-KR', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false, // 24시간 형식
    }); // 예: "15:05"

    return `${date} ${time}`; // 예: "2025년 1월 11일 금요일 15:05"
  };

  // 전송한 시간과 응답받은 시간에서 날짜는 제외하고 시:분만 표시
  const getTimeOnly = () => {
    const now = new Date();
    const time = now.toLocaleTimeString('ko-KR', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false, // 24시간 형식
    });
    return time; // 예: "15:05"
  };

  // 전송한 메시지와 응답 메시지 기록
  const handleSendMessage = async () => {
    if (userInput.trim() === "") return;

    // 사용자의 메시지와 전송 시간을 추가
    const sentTime = getTimeOnly();  // 시:분만 추가
    const newMessage = { sender: "사용자", message: userInput, time: sentTime };
    setChatHistory((prevHistory) => {
      const updatedHistory = [...prevHistory, newMessage];
      sessionStorage.setItem("chatHistory", JSON.stringify(updatedHistory));  // 세션 스토리지에 기록 저장
      return updatedHistory;
    });

    // 입력창 비우기
    setUserInput("");

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL}/chat`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          chatbotName: chatbotName,
          user_input: userInput,
          personality: personality,
        }),
      });
      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || "오류가 발생했습니다.");
      }

      const data = await response.json();
      const chatbotMessage = data.response;

      // 챗봇 응답 시간 기록
      const receivedTime = getTimeOnly();  // 시:분만 추가
      // 챗봇의 응답과 응답 시간을 추가
      setChatHistory((prevHistory) => {
        const updatedHistory = [
          ...prevHistory,
          { sender: chatbotName || chatbotName, message: chatbotMessage, time: receivedTime },
        ];
        sessionStorage.setItem("chatHistory", JSON.stringify(updatedHistory));  // 세션 스토리지에 기록 저장
        return updatedHistory;
      });
    } catch (error) {
      console.error("Error fetching chatbot response:", error);
      setError(error.message);

      // 욕설이 포함된 메시지가 있는 경우
      if (error.message.includes("부적절한 내용")) {
        alert("부적절한 내용은 사용할 수 없습니다. 다시 입력해주세요.");

        // 마지막으로 추가된 사용자 메시지만 삭제
        setChatHistory((prevHistory) => {
          const updatedHistory = prevHistory.slice(0, -1);
          sessionStorage.setItem("chatHistory", JSON.stringify(updatedHistory));  // 세션 스토리지에 기록 저장
          return updatedHistory;
        });
      }
    }
  };

  // 컴포넌트가 마운트될 때마다 시간을 갱신하도록 설정
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentDateTime(getCurrentDateTime());
    }, 1000); // 1초마다 시간을 갱신

    // 컴포넌트가 언마운트될 때 interval을 클리어
    return () => clearInterval(interval);
  }, []);

  // 새로고침 후, 세션 스토리지에서 대화 기록을 불러오기
  useEffect(() => {
    const savedHistory = JSON.parse(sessionStorage.getItem("chatHistory"));
    if (savedHistory) {
      setChatHistory(savedHistory);
    }
  }, []);

  // 채팅 기록이 변경될 때마다 스크롤을 맨 아래로 이동
  useEffect(() => {
    if (chatEndRef.current) {
      chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [chatHistory]);

  // 엔터 키를 눌렀을 때 메시지를 전송하도록 처리
  const handleKeyDown = (e) => {
    if (e.key === "Enter") {
      handleSendMessage();
    }
  };

  return (
    <div className={styles.chatContainer}>
      {/* 오늘 날짜와 시간을 맨 위에 실시간으로 표시 */}
      <div className={styles.chatDataTime}>
        <strong>{currentDateTime}</strong>
      </div>
      <div className={styles.chatHistory}>
        {chatHistory.map((chat, index) => (
          <div
            key={index}
            className={chat.sender === '사용자' ? styles.chatMessageUser : styles.chatMessageChatbot}
          >
            <strong>
              {chat.sender === "사용자" ? "사용자" : chatbotName}:
            </strong>
            <div>{chat.message}</div>
            {/* 사용자 메시지의 시간은 왼쪽 아래에 */}
            {chat.sender === '사용자' ? (
              <div className={styles.chatTimeUser}>
                <em>{chat.time}</em>
              </div>
            ) : (
              // 챗봇 메시지의 시간은 오른쪽 아래에
              <div className={styles.chatTimeChatbot}>
                <em>{chat.time}</em>
              </div>
            )}
          </div>
        ))}
        {/* 채팅이 끝난 부분에 추가된 ref로 스크롤을 내려줌 */}
        <div ref={chatEndRef} />
      </div>
      <div className={styles.chatInputArea}>
        <input
          type="text"
          value={userInput}
          onChange={(e) => setUserInput(e.target.value)}
          onKeyDown={handleKeyDown}  // 엔터 키 입력 감지
        />
        <button className={styles.chatSendButton} onClick={handleSendMessage}>전송</button>
      </div>
    </div>
  );
};

export default Chat;
